CREATE TABLE user (name TEXT NOT NULL, cash NUMERIC DEFAULT 0);
CREATE TABLE ahistory ( id INTEGER PRIMARY KEY, amount INTEGER NOT NULL, date TIMESTAMP DEFAULT CURRENT_TIMESTAMP, description TEXT);
CREATE TABLE phistory ( id INTEGER PRIMARY KEY, amount INTEGER NOT NULL, date TIMESTAMP DEFAULT CURRENT_TIMESTAMP, name TEXT NOT NULL, category TEXT NOT NULL, symbol TEXT UNIQUE NOT NULL);
CREATE TABLE items (symbol TEXT UNIQUE NOT NULL, name TEXT NOT NULL, price INTEGER NOT NULL, qrcode NUMERIC NOT NULL);